// BR-02: 5 wrong passwords in a row lock the account for 15 minutes.
export const MAX_FAILURES = 5;
export const LOCK_MINUTES = 15;

export function createLoginGuard(now = () => Date.now()) {
  const state = new Map(); // email -> { failures, lockedUntil }
  return {
    isLocked(email) {
      const s = state.get(email);
      return Boolean(s && s.lockedUntil > now());
    },
    recordFailure(email) {
      const s = state.get(email) ?? { failures: 0, lockedUntil: 0 };
      s.failures += 1;
      if (s.failures >= MAX_FAILURES) {
        s.lockedUntil = now() + LOCK_MINUTES * 60000;
        s.failures = 0;
      }
      state.set(email, s);
    },
    recordSuccess(email) {
      state.delete(email);
    },
  };
}

// Call fn up to `attempts` times; wait delayMs, then 2 × delayMs, … between attempts.
export async function retry(fn, { attempts = 3, delayMs = 1000 } = {}) {
  let lastError;
  for (let i = 1; i <= attempts; i++) {
    try {
      return await fn(i);
    } catch (err) {
      lastError = err;
      if (i < attempts) await new Promise((resolve) => setTimeout(resolve, delayMs * i));
    }
  }
  throw lastError;
}

// Lite-3: a booking can be cancelled until 60 minutes before it starts.
export const CANCEL_LIMIT_MINUTES = 60;

export function canCancel(startsAt, now = new Date()) {
  const minutesLeft = (startsAt.getTime() - now.getTime()) / 60000;
  return minutesLeft >= CANCEL_LIMIT_MINUTES;
}

// Chapter 11 (US-11 "My bookings"): when does a booking start, and may this user cancel it now?
// A booking's date and start are Viet Nam wall-clock time (UTC+7), whatever the server's time zone.
export function startsAtVN(date, start) {
  return new Date(date + 'T' + start + ':00+07:00');
}

// booking: { userId, status, date, start } or null · user: { id, role } · now: a Date.
export function cancelDecision(booking, user, now) {
  const isAdmin = user.role === 'ADMIN';
  if (!booking || (booking.userId !== user.id && !isAdmin)) return { ok: false, code: 'NOT_FOUND' };
  if (booking.status === 'CANCELLED') return { ok: false, code: 'ALREADY_CANCELLED' };
  if (!isAdmin && !canCancel(startsAtVN(booking.date, booking.start), now)) return { ok: false, code: 'TOO_LATE_TO_CANCEL' };
  return { ok: true };
}

// BR-05 needs "days ahead" counted in Viet Nam's calendar (UTC+7), whatever the server's time zone.
const VN_OFFSET_MS = 7 * 60 * 60 * 1000;
const DAY_MS = 24 * 60 * 60 * 1000;

export function daysAheadVN(dateText, now = new Date()) {
  const todayVN = new Date(now.getTime() + VN_OFFSET_MS).toISOString().slice(0, 10);
  return Math.round((Date.parse(dateText + 'T00:00:00Z') - Date.parse(todayVN + 'T00:00:00Z')) / DAY_MS);
}

